#include <iostream>
#include <sstream>

void summarize(std::istream& input) {
    int count = 0;
    long long sum = 0;
    while (true) {
        input >> std::ws;
        if (input.eof()) break;
        int value{};
        if (!(input >> value) || value < -1000 || value > 1000 || count == 100) {
            std::cout << "ОШИБКА\n";
            return;
        }
        ++count;
        sum += value;
    }
    std::cout << count << ' ' << sum << '\n';
}
int main() {
    summarize(std::cin);
}
